func (q *Queries) SaveFarmer(ctx context.Context, arg SaveFarmerParams) (Farmer, error) {
	row := q.db.QueryRow(ctx, saveFarmer,
		arg.Phone,
		arg.Name,
		arg.NameTe,
		arg.Language,
		arg.VillageID,
		arg.MandalID,
		arg.DistrictID,
		arg.AssignedFaID,
		arg.EnrolledByFaID,
		arg.PhotoKey,
		arg.Plan,
		arg.Status,
		arg.ProfileCompletedAt,
		arg.LastCommandID,
		arg.ID,
	)
	var i Farmer
	err := row.Scan(
		&i.ID,
		&i.Phone,
		&i.Name,
		&i.NameTe,
		&i.Language,
		&i.VillageID,
		&i.AssignedFaID,
		&i.Source,
		&i.EnrolledByFaID,
		&i.PhotoKey,
		&i.Plan,
		&i.Status,
		&i.ProfileCompletedAt,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.MandalID,
		&i.DistrictID,
		&i.LastCommandID,
	)
	return i, err
}

const targetFarmerIDs = `-- name: TargetFarmerIDs :many
SELECT f.id
FROM farmers f
WHERE f.status = 'active'
  AND ($1::text IS NULL OR f.plan = $1)
  AND (cardinality($2::uuid[]) = 0 OR f.village_id = ANY($2::uuid[]))
  AND (cardinality($3::uuid[]) = 0 OR f.mandal_id = ANY($3::uuid[]))
  AND (cardinality($4::uuid[]) = 0 OR f.district_id = ANY($4::uuid[]))
  AND (cardinality($5::uuid[]) = 0 OR EXISTS (
        SELECT 1 FROM crop_seasons s
        WHERE s.farmer_id = f.id AND s.status = 'active' AND s.crop_id = ANY($5::uuid[])))
  AND (SELECT c.granted FROM consents c
       WHERE c.farmer_id = f.id AND c.purpose = 'programme'
       ORDER BY c.created_at DESC, c.id DESC LIMIT 1) IS TRUE
ORDER BY f.id
`

type TargetFarmerIDsParams struct {
	Plan        *string     `json:"plan"`
	VillageIds  []uuid.UUID `json:"village_ids"`
	MandalIds   []uuid.UUID `json:"mandal_ids"`
	DistrictIds []uuid.UUID `json:"district_ids"`
	CropIds     []uuid.UUID `json:"crop_ids"`
}

// Active farmers whose current programme consent is granted. Every non-empty
// filter narrows the audience (AND): plan, villages, mandals, districts and
// crop of an active season. An empty list means "any".
func (q *Queries) TargetFarmerIDs(ctx context.Context, arg TargetFarmerIDsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, targetFarmerIDs,
		arg.Plan,
		arg.VillageIds,
		arg.MandalIds,
		arg.DistrictIds,
		arg.CropIds,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
